import inspect
import math
from collections import Counter
from statistics import median


def _cartesian_mover(api):
    """Adapt common Cartesian-motion signatures; never use joint motion."""
    names = (
        "move_to", "move_tcp", "move_ee", "move_linear",
        "movel", "move", "set_tcp_pose",
    )

    def argument(name, xyz):
        key = name.lower()
        if key in ("x", "y", "z"):
            return xyz["xyz".index(key)]
        if key in (
            "position", "pos", "xyz", "target", "target_pos",
            "target_position", "translation",
        ):
            return list(xyz)
        if key in ("pose", "tcp_pose", "target_pose"):
            return list(xyz) + [math.pi, 0.0, 0.0]
        if key in ("orientation", "quaternion", "quat", "target_orn"):
            return [1.0, 0.0, 0.0, 0.0]  # xyzw; tool points down
        if key in ("rotvec", "rotation_vector", "rpy"):
            return [math.pi, 0.0, 0.0]
        if key in ("rx", "roll"):
            return math.pi
        if key in ("ry", "rz", "pitch", "yaw"):
            return 0.0
        if key in ("speed", "velocity", "v"):
            return 0.10
        if key in ("acceleration", "accel", "a"):
            return 0.25
        if key in ("wait", "blocking"):
            return True
        raise KeyError(name)

    position_names = {
        "x", "y", "z", "position", "pos", "xyz", "target",
        "target_pos", "target_position", "translation",
        "pose", "tcp_pose", "target_pose",
    }

    for name in names:
        method = getattr(api, name, None)
        if not callable(method):
            continue
        try:
            parameters = list(inspect.signature(method).parameters.values())
        except (TypeError, ValueError):
            continue

        if not any(p.name.lower() in position_names for p in parameters):
            continue

        def build(xyz, parameters=parameters):
            args, kwargs = [], {}
            for p in parameters:
                if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                    continue
                try:
                    value = argument(p.name, xyz)
                except KeyError:
                    if p.default is p.empty:
                        raise ValueError("Unsupported required motion argument")
                    if p.kind == p.POSITIONAL_ONLY:
                        args.append(p.default)
                    continue
                if p.kind == p.POSITIONAL_ONLY:
                    args.append(value)
                else:
                    kwargs[p.name] = value
            return args, kwargs

        try:
            build((0.4, 0.0, 0.18))
        except ValueError:
            continue

        def move(x, y, z, method=method, build=build):
            args, kwargs = build((float(x), float(y), float(z)))
            result = method(*args, **kwargs)
            if result is False:
                raise RuntimeError("Cartesian motion failed")
            return result

        return move

    raise RuntimeError("No supported Cartesian-motion API was found")


