    readings = [api.cube_pose() for _ in range(count)]
    position = [
        median(float(reading[0][axis]) for reading in readings)
        for axis in range(3)
    ]
    colour = Counter(reading[2] for reading in readings).most_common(1)[0][0]
    return position, colour


