    bx, by = float(bin_position[0]), float(bin_position[1])
    rim_z = float(bin_position[2])
    safe_z = max(safe_z, rim_z + cube_size + 0.06)

    # Search downward conservatively: reported pose height may refer to the
    # top surface or the object centre. Verify grasp by actual object motion,
    # rather than treating the suction command's return value as attachment.
    grasped = False
    for _ in range(2):
        position, observed_colour = _observe(api)
        if observed_colour != colour:
            raise RuntimeError("Inconsistent colour observations")

        x, y, z = position
        move(x, y, safe_z)

        contact_floor = cube_size - 0.002
        heights = sorted(
            {
                max(contact_floor, z + offset)
                for offset in (0.025, 0.019, 0.013, 0.007, 0.001, -0.003)
            },
            reverse=True,
        )

        for contact_z in heights:
            api.suction(on=False)
            position, observed_colour = _observe(api)
            if observed_colour != colour:
                raise RuntimeError("Inconsistent colour observations")
            x, y, before_z = position

            move(x, y, safe_z)
            move(x, y, contact_z)
            api.suction(on=True)
            move(x, y, contact_z + 0.025)

            lifted, _ = _observe(api)
