    # the walls during horizontal travel.
    offset_x = carried[0] - x
    offset_y = carried[1] - y
    place_x = bx - offset_x
    place_y = by - offset_y

    move(place_x, place_y, safe_z)

    # A centred 40 mm cube fits at every yaw in the 120 mm opening.
    # Release slightly above the rim rather than pressing against the floor.
    release_z = rim_z + 0.025
    move(place_x, place_y, release_z)
    api.suction(on=False)
    move(place_x, place_y, safe_z)

    # These harmless motions also advance simulators whose physics advances
    # only during API actions, allowing the released cube to settle.
    for i in range(8):
        if api.done():
            return
        move(place_x, place_y, safe_z + (0.01 if i % 2 == 0 else 0.0))

    if not api.done():
        raise RuntimeError("Cube released, but successful sorting was not confirmed")
