import inspect
import math
import statistics
import time


_LAST_TCP = [0.4504, -0.0489, 0.1503]
_CLEARANCE = 0.160
_CUBE_TOP = 0.040


def _call(fn, arguments=None):
    """Support both keyword-style and request-dictionary API wrappers."""
    arguments = {} if arguments is None else arguments
    try:
        sig = inspect.signature(fn)
    except (TypeError, ValueError):
        return fn(**arguments)

    params = list(sig.parameters.values())
    ordinary = [
        p for p in params
        if p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD)
    ]
    if (
        len(ordinary) == 1
        and ordinary[0].name.lower()
        in ("args", "arguments", "params", "request", "payload", "command")
    ):
        return fn(arguments)
    if not arguments and len(ordinary) == 1:
        p = ordinary[0]
        if p.default is inspect.Parameter.empty:
            return fn({})
    return fn(**arguments)


def _methods(api, preferred):
    names = list(preferred)
    try:
        names.extend(n for n in dir(api) if not n.startswith("_"))
    except Exception:
        pass

    seen = set()
    for name in names:
        if name in seen:
            continue
        seen.add(name)
        try:
            fn = getattr(api, name)
        except AttributeError:
            continue
        if callable(fn):
            yield name, fn


def _getter(api, names):
    for name in names:
        try:
            fn = getattr(api, name)
        except AttributeError:
            continue
        if callable(fn):
            return fn
    return None


def _position(value):
    if isinstance(value, dict):
        for key in ("tcp_pose", "ee_pose", "tool_pose", "pose"):
            if key in value:
                return _position(value[key])
        for key in ("position", "translation", "xyz", "tcp_position"):
            if key in value:
                return _position(value[key])
        if all(k in value for k in ("x", "y", "z")):
            return [float(value[k]) for k in ("x", "y", "z")]
    if isinstance(value, (list, tuple)):
        if len(value) >= 3 and all(
            isinstance(v, (int, float)) for v in value[:3]
        ):
            return list(map(float, value[:3]))
        if value:
            return _position(value[0])
    raise ValueError("Unrecognized Cartesian position representation")


