        "move_tool", "move_to", "move_xyz", "move_linear", "movel",
        "move_l", "set_tcp_pose", "set_ee_pose", "set_end_effector_pose",
        "move_relative", "translate", "move",
    )

    def __init__(self, api):
        self.api = api
        self.current = list(_LAST_TCP)
