        for name, fn in _methods(api, self.NAMES):
            lower = name.lower()
            if any(s in lower for s in ("joint", "reset", "velocity", "force")):
                continue
            if name not in self.NAMES and not (
                any(s in lower for s in ("move", "set", "translate"))
