                if result is False:
                    raise RuntimeError("Motion command was rejected")
                return result

            yield command
            return

        # Opaque wrappers: try only ordinary Cartesian request schemas.
        if relative:
            schemas = ("delta", "dxyz")
        elif name.lower() in ("movel", "move_l", "set_tcp_pose", "set_ee_pose"):
            schemas = ("pose", "position", "xyz")
        else:
            schemas = ("xyz", "position", "target_position", "pose")

        for schema in schemas:
            def command(target, speed, schema=schema):
                delta = [target[i] - self.current[i] for i in range(3)]
                if schema == "xyz":
                    args = dict(zip(("x", "y", "z"), target))
                elif schema == "dxyz":
                    args = dict(zip(("dx", "dy", "dz"), delta))
                elif schema == "delta":
                    args = {"delta": delta}
                elif schema == "pose":
                    args = {"pose": list(target) + [math.pi, 0.0, 0.0]}
                else:
                    args = {schema: list(target)}
                result = _call(fn, args)
                if result is False:
                    raise RuntimeError("Motion command was rejected")
                return result
            yield command

    def move(self, target, speed=0.06):
        target = list(map(float, target))
        self.command(target, speed)

        if self.reader is not None:
            deadline = time.monotonic() + 20.0
            while True:
                actual = _position(_call(self.reader))
                if math.dist(actual, target) < 0.002:
                    self.current = actual
                    break
                if time.monotonic() > deadline:
                    raise RuntimeError("Cartesian motion did not reach its target")
                time.sleep(0.02)
        else:
            # Without feedback, the selected command must be blocking.
            self.current = target


class _JointServo:
    """Fallback for joint-only APIs with measured full TCP-pose feedback.

    A measured Jacobian avoids assuming the simulator's robot-base transform,
    tool length, or joint zero offsets.
    """

    def __init__(self, api):
        import numpy as np
        self.np = np
        self.qread = _getter(
            api, ("get_joint_positions", "joint_positions",
                  "get_joint_angles", "joint_angles", "get_joints")
        )
        self.pread = _getter(
            api, ("get_tcp_pose", "tcp_pose", "get_actual_tcp_pose",
                  "get_ee_pose", "ee_pose", "get_tool_pose",
                  "get_end_effector_pose")
