            if all(k in value for k in ("x", "y", "z", "w")):
                value = [value[k] for k in ("x", "y", "z", "w")]
                kind = "quaternion"
            elif all(k in value for k in ("roll", "pitch", "yaw")):
                value = [value[k] for k in ("roll", "pitch", "yaw")]
                kind = "rpy"
        v = np.asarray(value, dtype=float)
        if v.shape == (3, 3):
            return v
        if v.shape == (4,):
            x, y, z, w = v / np.linalg.norm(v)
            return np.array([
                [1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
                [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
                [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)],
