        p0, R0 = self._read_pose()
        columns = []
        for j in range(6):
            q = q0.copy()
            q[j] += 0.003
            self._write(q)
            p, R = self._read_pose()
            columns.append(np.r_[p-p0, self._angle_error(R, R0)] / 0.003)
