            p1, R1 = self._read_pose()
            actual_dq = self.q - q0
            change = np.r_[p1-p, self._angle_error(R1, R)]
            denominator = actual_dq @ actual_dq
            if denominator > 1e-10:
                self.J += np.outer(
                    change - self.J @ actual_dq, actual_dq
