"""Resume the cell without resetting it.

The reported cube XY/yaw is inconsistent with the stated placement envelope.
Use its colour, but search the known placement envelope for the grasp.
"""

import inspect
import math
import numpy as np


def _find(api, names):
    for name in names:
        fn = getattr(api, name, None)
        if callable(fn):
            return fn
    return None


def _bind(fn, values):
    """Prepare a call without executing trial motion commands."""
    try:
        signature = inspect.signature(fn)
    except (TypeError, ValueError):
        return None

    args, kwargs = [], {}
    supplied = 0
    for name, parameter in signature.parameters.items():
        if parameter.kind in (
            inspect.Parameter.VAR_POSITIONAL,
            inspect.Parameter.VAR_KEYWORD,
        ):
            continue
        if name in values:
            value = values[name]
            supplied += 1
        elif parameter.default is not inspect.Parameter.empty:
            if parameter.kind == inspect.Parameter.POSITIONAL_ONLY:
                value = parameter.default
            else:
                continue
        else:
            return None
        if parameter.kind == inspect.Parameter.POSITIONAL_ONLY:
            args.append(value)
        else:
            kwargs[name] = value

    if not supplied:
        return None
    return lambda: fn(*args, **kwargs)


def _rotation(v, euler=False):
    v = np.asarray(v, dtype=float)
    if v.shape == (3, 3):
        return v
    if v.size == 4:
        # Quaternion convention: x, y, z, w.
        x, y, z, w = v / np.linalg.norm(v)
        return np.array([
            [1 - 2*(y*y + z*z), 2*(x*y - z*w), 2*(x*z + y*w)],
            [2*(x*y + z*w), 1 - 2*(x*x + z*z), 2*(y*z - x*w)],
            [2*(x*z - y*w), 2*(y*z + x*w), 1 - 2*(x*x + y*y)],
        ])
    if v.size != 3:
        raise ValueError("Full TCP orientation is required.")
    if euler:
        r, p, y = v
        cr, sr, cp, sp, cy, sy = (
            math.cos(r), math.sin(r), math.cos(p),
            math.sin(p), math.cos(y), math.sin(y),
        )
        return np.array([
            [cy*cp, cy*sp*sr - sy*cr, cy*sp*cr + sy*sr],
            [sy*cp, sy*sp*sr + cy*cr, sy*sp*cr - cy*sr],
            [-sp, cp*sr, cp*cr],
        ])
    angle = np.linalg.norm(v)
    if angle < 1e-12:
        return np.eye(3)
    x, y, z = v / angle
    k = np.array([[0, -z, y], [z, 0, -x], [-y, x, 0]])
    return np.eye(3) + math.sin(angle)*k + (1-math.cos(angle))*(k @ k)


def _rotation_error(target, current):
    r = target @ current.T
    angle = math.acos(float(np.clip((np.trace(r)-1)/2, -1, 1)))
    skew = np.array([r[2, 1]-r[1, 2],
                     r[0, 2]-r[2, 0],
                     r[1, 0]-r[0, 1]])
    if angle < 1e-6:
        return 0.5 * skew
    return angle / (2 * math.sin(angle)) * skew


def _pose(raw, euler=False):
    if isinstance(raw, dict):
        position = raw.get("position", raw.get("translation", raw.get("xyz")))
        if position is None and all(k in raw for k in ("x", "y", "z")):
            position = [raw["x"], raw["y"], raw["z"]]
        orientation = None
        for key in ("quaternion", "rotation_vector", "rotvec",
                    "rpy", "orientation", "rotation"):
            if key in raw:
                orientation = raw[key]
                euler = key == "rpy" or euler
                break
        if isinstance(orientation, dict):
            keys = ("x", "y", "z", "w")
            orientation = [orientation[k] for k in keys]
    else:
        if len(raw) == 2 and hasattr(raw[0], "__len__"):
            position, orientation = raw
        else:
            a = np.asarray(raw, dtype=float)
            if a.shape == (4, 4):
                return a[:3, 3], a[:3, :3], None
            position, orientation = a[:3], a[3:]

    if position is None or orientation is None:
        raise ValueError("TCP feedback does not contain a full pose.")
    return (np.asarray(position, dtype=float),
            _rotation(orientation, euler),
            np.asarray(orientation, dtype=float).tolist())


class _Motion:
    def __init__(self, api):
        self.api = api
        self.xyz = np.array([0.4504, -0.0489, 0.1503])
        self.orientation = [math.pi, 0.0, 0.0]
        self.pose_fn = _find(api, (
            "tcp_pose", "get_tcp_pose", "get_actual_tcp_pose",
            "get_ee_pose", "ee_pose", "get_tool_pose", "tool_pose",
        ))
        self.euler = False
        if self.pose_fn:
            doc = (inspect.getdoc(self.pose_fn) or "").lower()
            self.euler = "euler" in doc or "roll, pitch, yaw" in doc
            self.xyz, self.rotation, orientation = self.read_pose()
            if orientation is not None:
                self.orientation = orientation
        else:
            self.rotation = _rotation(self.orientation)

        self.cartesian = None
        candidates = (
            "move_tcp", "move_cartesian", "move_to", "move_xyz",
            "move_linear", "movel", "moveL", "set_tcp_pose",
            "move_ee", "move_tool", "move",
        )
        for name in candidates:
            fn = getattr(api, name, None)
            if callable(fn) and _bind(fn, self.cartesian_values(self.xyz)):
                self.cartesian = fn
                break

        self.joint_read = None
        self.joint_write = None
        if self.cartesian is None:
            self.joint_read = _find(api, (
                "joint_positions", "get_joint_positions",
                "get_actual_joint_positions", "get_joint_angles",
                "joint_angles", "get_joints",
            ))
            if not self.pose_fn or not self.joint_read:
                raise RuntimeError(
                    "Cannot safely move: the API exposes neither a supported "
                    "Cartesian command nor joint positions plus full TCP pose."
                )
            q = self.read_joints()
            for name in (
                "move_joints", "move_joint", "movej", "moveJ",
                "set_joint_positions", "set_joints",
            ):
                fn = getattr(api, name, None)
                if callable(fn) and _bind(fn, self.joint_values(q)):
                    self.joint_write = fn
                    break
            if self.joint_write is None:
                raise RuntimeError("No supported joint-position command found.")

    def read_pose(self):
        return _pose(self.pose_fn(), self.euler)

    def read_joints(self):
        result = self.joint_read()
        if isinstance(result, dict):
            for key in ("joint_positions", "positions", "joints", "q", "angles"):
                if key in result:
                    result = result[key]
                    break
        q = np.asarray(result, dtype=float)
        if q.shape != (6,):
            raise RuntimeError("Expected six joint positions, in radians.")
        return q

    def cartesian_values(self, target):
        target = np.asarray(target, dtype=float)
        p = target.tolist()
        o = self.orientation
        flat_pose = p + list(o) if np.asarray(o).ndim == 1 else [p, o]
        delta = target - self.xyz
        values = {
            "x": p[0], "y": p[1], "z": p[2],
            "dx": float(delta[0]), "dy": float(delta[1]),
            "dz": float(delta[2]),
            "position": p, "target_position": p, "xyz": p,
            "target": p,
            "pose": flat_pose, "tcp_pose": flat_pose,
            "target_pose": flat_pose,
            "orientation": o, "rotation": o,
            "speed": 0.08, "velocity": 0.08, "v": 0.08,
            "acceleration": 0.25, "a": 0.25,
            "wait": True, "blocking": True,
        }
        if len(o) == 3:
            values.update(rx=o[0], ry=o[1], rz=o[2])
            if self.euler:
                values.update(roll=o[0], pitch=o[1], yaw=o[2])
        return values

    @staticmethod
    def joint_values(q):
        q = np.asarray(q).tolist()
        values = {
            "q": q, "joints": q, "positions": q,
            "joint_positions": q, "angles": q,
            "target": q, "target_joints": q,
            "speed": 0.15, "velocity": 0.15, "v": 0.15,
            "acceleration": 0.3, "a": 0.3,
            "wait": True, "blocking": True,
        }
        values.update({"j%d" % (i + 1): value for i, value in enumerate(q)})
        return values

    def write_joints(self, q):
        call = _bind(self.joint_write, self.joint_values(q))
        if call is None:
            raise RuntimeError("Unsupported joint command signature.")
        call()

    def joint_to(self, target):
        # Small, feedback-controlled steps; retain the initial downward attitude.
        target = np.asarray(target, dtype=float)
        for _ in range(100):
            p, r, _ = self.read_pose()
            dp = target - p
            dr = _rotation_error(self.rotation, r)
            if np.linalg.norm(dp) < 0.0008 and np.linalg.norm(dr) < 0.008:
                self.xyz = p
                return
            q = self.read_joints()
            jac = np.zeros((6, 6))
            epsilon = 0.001
            for j in range(6):
                probe = q.copy()
                probe[j] += epsilon
                self.write_joints(probe)
                pp, rr, _ = self.read_pose()
                actual = self.read_joints()[j] - q[j]
                if abs(actual) < 1e-7:
                    self.write_joints(q)
                    raise RuntimeError("Joint command did not reach its probe.")
                jac[:3, j] = (pp - p) / actual
                jac[3:, j] = 0.1 * _rotation_error(rr, r) / actual
