            dp *= min(1.0, 0.008 / max(np.linalg.norm(dp), 1e-12))
            dr *= min(1.0, 0.05 / max(np.linalg.norm(dr), 1e-12))
            error = np.r_[dp, 0.1 * dr]
            dq = jac.T @ np.linalg.solve(
                jac @ jac.T + 1e-5 * np.eye(6), error
            )
            dq *= min(1.0, 0.035 / max(np.max(np.abs(dq)), 1e-12))
            self.write_joints(q + dq)
