    def to(self, x, y, z):
        goal = np.array([x, y, z], dtype=float)
        if self.cartesian is None:
            self.joint_to(goal)
            return

        # Segmentation also limits the distance of a relative-motion command.
        for _ in range(200):
            if self.pose_fn:
                self.xyz = self.read_pose()[0]
            difference = goal - self.xyz
            distance = np.linalg.norm(difference)
            if distance < 0.0007:
