            waypoint = self.xyz + difference * min(1.0, 0.015 / distance)
            call = _bind(self.cartesian, self.cartesian_values(waypoint))
            if call is None:
                raise RuntimeError("Unsupported Cartesian command signature.")
            call()
            if not self.pose_fn:
                self.xyz = waypoint
        raise RuntimeError("Cartesian motion failed to converge; stopping.")


def run(api):
